# Qosha upgrade for a Qosha installed before it could update itself (Windows). Made by Qosha's release tool.
# Everything it installs is checked against Qosha's signature first; if any check fails, nothing is changed.
#   powershell -NoProfile -ExecutionPolicy Bypass -File upgrade-qosha.ps1 [-Ring renato]
param([string]$Ring = 'everyone', [string]$Root = (Join-Path $env:LOCALAPPDATA 'Qosha'), [string[]]$Source = @(), [switch]$Foreground)
$ErrorActionPreference = 'Continue'
# run from Qosha's own chat: the Qosha that runs it (its home is HERMES_HOME), else the standard place
if (-not $PSBoundParameters.ContainsKey('Root') -and $env:HERMES_HOME -and (Test-Path (Join-Path (Split-Path $env:HERMES_HOME) 'layer\setup_home.py'))) { $Root = Split-Path $env:HERMES_HOME }
if (-not (Test-Path (Join-Path $Root 'layer\setup_home.py'))) { 'Qosha was not found on this computer. Nothing on this computer was changed.'; exit 2 }
$py = $null
Get-ChildItem -Path (Join-Path $Root 'home\installs\*\environments\*\venv\Scripts\python.exe') -ErrorAction SilentlyContinue |
  Sort-Object LastWriteTime -Descending | ForEach-Object { if (-not $py) { & $_.FullName -I -c 'import cryptography' 2>$null; if ($LASTEXITCODE -eq 0) { $py = $_.FullName } } }
if (-not $py) { 'Qosha cannot check the signature of the update on this computer. Nothing on this computer was changed.'; exit 2 }
New-Item -ItemType Directory -Force -Path (Join-Path $Root 'run'), (Join-Path $Root 'logs') | Out-Null
$f = Join-Path $Root 'run\qosha-upgrade.py'
[IO.File]::WriteAllBytes($f, [Convert]::FromBase64String(''))
$a = @('-I', $f, '--root', $Root, '--ring', $Ring); foreach ($s in $Source) { $a += @('--source', $s) }; if ($Foreground) { $a += '--foreground' }
& $py @a
$rc = $LASTEXITCODE
if ($PSCommandPath -and ((Split-Path $PSCommandPath -Leaf) -eq 'qosha-upgrade.ps1')) { Remove-Item $PSCommandPath -ErrorAction SilentlyContinue }
exit $rc
